from __future__ import annotations
from html import escape
from .dataio import write_text, ROOT, synthetic_banner, load_json, DATA
from .intake import intake_evaluation, process_submissions
from .wording import qa_evaluation
from .review import review_results
from .inventory import portfolio_insight

def _table(headers,rows):
    head="".join(f"<th>{escape(str(h))}</th>" for h in headers)
    body="".join("<tr>"+"".join(f"<td>{escape(str(x))}</td>" for x in row)+"</tr>" for row in rows)
    return f"<table><thead><tr>{head}</tr></thead><tbody>{body}</tbody></table>"

def render_dashboard():
    ie=intake_evaluation(); qa=qa_evaluation(); reviews=review_results(); insight=portfolio_insight(); controls=load_json(DATA/"controls"/"rai_controls.json")["controls"]
    outcomes=process_submissions()
    mrows=[["Submission field accuracy",f"{ie['fields_correct']}/{ie['field_values_total']}",f"{ie['field_level_accuracy']:.1%}"],["Submissions routed to review",f"{ie['human_review_count']}/{ie['labelled_submissions']}","synthetic cases"],["Wording outcome accuracy",f"{qa['outcomes_correct']}/{qa['labelled_questions']}",f"{qa['outcome_accuracy']:.1%}"],["Citation validity",f"{qa['citation_ids_valid']}/{qa['citation_ids_total']}",f"{qa['citation_validity']:.1%}"],["Refusal correctness",f"{qa['refusal_correct']}/{qa['refusal_total']}",f"{qa['refusal_correctness']:.1%}"]]
    orows=[[r["submission_id"],r["status"],", ".join(r["reason_codes"]) or "No validation failures"] for r in outcomes]
    rrows=[[r["use_case"],r["gate_stage"],r["outcome"],"; ".join(r["conditions"]) or "None"] for r in reviews]
    crows=[[c["control_id"],c["owner_role"],c["risk"],c["status"],c["implementation_reference"],c["evidence_produced"]] for c in controls]
    irows=[["Use cases with evaluation sets",f"{insight['use_cases_with_evaluation']}/{insight['use_case_count']}",""],["Use cases with owner role",f"{insight['use_cases_with_owner']}/{insight['use_case_count']}",""],["Standards adoption",f"{insight['standards_adoption_numerator']}/{insight['standards_adoption_denominator']}",f"{insight['standards_adoption_percent']:.1f}%"],["Use cases reusing services",f"{insight['reuse_numerator']}/{insight['reuse_denominator']}",""]]
    rec="".join(f"<li>{escape(x)}</li>" for x in insight["recommendations"])
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Synthetic AI Architecture Portfolio</title><style>
:root{{--navy:#0b2a4a;--teal:#087e8b;--ink:#25394b;--muted:#617486;--line:#d9e2ea;--wash:#f3f7fa}}*{{box-sizing:border-box}}body{{margin:0;background:var(--wash);font:15px/1.5 system-ui,Segoe UI,Arial,sans-serif;color:var(--ink)}}header{{background:var(--navy);color:white;padding:26px max(22px,calc((100vw - 1180px)/2))}}header h1{{margin:0;font-size:28px}}header p{{margin:8px 0 0;color:#d8e6ef}}main{{max-width:1180px;margin:22px auto;padding:0 22px}}.banner{{font-weight:700;color:#6b4000;background:#fff2dc;border:1px solid #edcf9b;padding:12px 16px;border-radius:8px;margin-bottom:18px}}section{{background:white;border:1px solid var(--line);border-radius:10px;padding:18px 20px;margin:15px 0}}h2{{margin:0 0 12px;color:var(--navy);font-size:20px}}h3{{color:var(--teal)}}.grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px}}.metric{{border:1px solid var(--line);border-radius:8px;padding:14px}}.metric b{{display:block;font-size:22px;color:var(--navy)}}.metric span{{color:var(--muted)}}table{{width:100%;border-collapse:collapse;font-size:13px}}th,td{{text-align:left;padding:9px;border:1px solid var(--line);vertical-align:top}}th{{background:#e8f0f6;color:var(--navy)}}tr:nth-child(even) td{{background:#f8fafc}}.note{{color:var(--muted);font-size:13px}}footer{{max-width:1180px;margin:20px auto;padding:15px 22px;color:var(--muted);font-size:12px}}@media(max-width:700px){{main{{padding:0 12px}}section{{padding:14px}}table{{display:block;overflow-x:auto}}}}</style></head><body><header><h1>Synthetic AI Architecture Portfolio</h1><p>Illustrative underwriting and wording-assistance use cases, governance evidence and portfolio insight.</p></header><main><div class="banner">{escape(synthetic_banner())} No production, insurer or broker data is used.</div><section><h2>Evaluation overview</h2><div class="grid">{''.join(f'<div class="metric"><b>{escape(v)}</b><span>{escape(k)}</span></div>' for k,n,v in mrows)}</div><p class="note">Evaluation sets are author-labelled and small. Percentages describe only these synthetic sets and are not production performance claims.</p></section><section><h2>Submission intake outcomes</h2>{_table(['Submission','Status','Validation reasons'],orows)}</section><section><h2>Design-authority review</h2>{_table(['Use case','Gate stage','Outcome','Conditions'],rrows)}</section><section><h2>Responsible AI control matrix</h2>{_table(['Control','Owner role','Risk','Status','Implementation','Evidence'],crows)}<p class="note">Any regulatory or Responsible-AI references are illustrative mappings, not statements of requirements.</p></section><section><h2>Portfolio insight</h2>{_table(['Metric','Numerator / denominator','Value'],irows)}<h3>Deterministic recommendations</h3><ul>{rec}</ul><p class="note">All portfolio counts use explicit numerators and denominators. Inventory is synthetic.</p></section></main><footer>Personal prototype • synthetic data • illustrative policies • no production use</footer></body></html>'''

def write_dashboard():
    return str(write_text(ROOT/"docs"/"index.html",render_dashboard()))
